// The recommendation-sorting 3.3 goldens: the four spec scenarios the scored
// ordering must hold in production shape — asserted over the REAL router and
// a real store, reusing the landed 3.1 fixtures idioms (newRecsAPI and the
// seedRecs* helpers). Each golden forces the scored order and the store
// order to DIFFER, so a green run can never be a tie-break accident.

// seedGoldenPhotoItem puts one image-module item row into the photo library
// and returns the stored row (the seedRecsItem idiom; ModuleID/MediaType
// carry the image module the library row binds).
func seedGoldenPhotoItem(t *testing.T, st *store.Store, libraryID int64, id, relPath, title string) store.Item {
	t.Helper()
	doc := map[string]any{
		"_view": map[string]any{"title": map[string]any{"value": title}},
	}
	if err := st.PutItem(context.Background(), store.Item{
		ID: id, ModuleID: "image", LibraryID: libraryID, FileID: id,
		RelativePath: relPath, MediaType: "image",
		Document: recsDoc(t, doc), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
	got, err := st.GetItem(context.Background(), id, access.System())
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	return got
}

// wireHasRecScore re-marshals one DTO and reports whether rec_score rode
// the wire (the omitempty omission is the scored-absence proof).
func wireHasRecScore(t *testing.T, d any) bool {
	t.Helper()
	b, err := json.Marshal(d)
	if err != nil {
		t.Fatalf("remarshal wire row: %v", err)
	}
	var wire map[string]any
	if err := json.Unmarshal(b, &wire); err != nil {
		t.Fatalf("unmarshal wire row: %v", err)
	}
	_, has := wire["rec_score"]
	return has
}

// TestGoldenStartedSerialTopsGrid is the spec's "A started serial with a new
// episode tops the grid" scenario: one started series (an episode under
// progress) gained an unwatched episode this week; the back catalog is
// unstarted. The scored default places the started series above every
// unstarted one EVEN THOUGH path order would put the catalog first, and
// sort=path restores the alphabetical order unscored.
func TestGoldenStartedSerialTopsGrid(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// The back catalog sorts BEFORE the ongoing series in path order — the
	// scored default must invert exactly that.
	aa := seedRecsSeries(t, st, lib, "aa-backlog", recsSeriesDoc("Backlog A"))
	bb := seedRecsSeries(t, st, lib, "bb-backlog", recsSeriesDoc("Backlog B"))
	cc := seedRecsSeries(t, st, lib, "cc-backlog", recsSeriesDoc("Backlog C"))
	ongoing := seedRecsSeries(t, st, lib, "dd-ongoing", recsSeriesDoc("Ongoing"))
	epStarted := seedRecsItem(t, st, lib, "gld_s1", "dd-ongoing/e1.mkv", recsEpisodeDoc("dd-ongoing", ""), time.Now().AddDate(0, 0, -40))
	if _, err := st.PutProgress(ctx, epStarted.ID, 300, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	// The fresh entry: discovered this week, unwatched — the 1500 stack
	// (resume 1000 + new episode 500).
	seedRecsItem(t, st, lib, "gld_s2", "dd-ongoing/e2.mkv", recsEpisodeDoc("dd-ongoing", ""), time.Time{})

	resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib), "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	rows := decodeSeriesList(t, resp)
	got := servedIDs(rows, func(d seriesDTO) string { return d.ID })
	// The started series tops the grid; the unstarted catalog ties at zero
	// behind it (the alphabetical floor orders the tie).
	wantIDs(t, got, ongoing.ID, aa.ID, bb.ID, cc.ID)
	if rows[0].RecScore != 1500 {
		t.Fatalf("started series rec_score = %v, want 1500 (resume + new episode)", rows[0].RecScore)
	}
	for _, d := range rows[1:] {
		if d.RecScore != 0 {
			t.Fatalf("unstarted series %s carried rec_score %v", d.ID, d.RecScore)
		}
	}

	// sort=path restores today's alphabetical order, unscored — the back
	// catalog back on top, the started series last.
	resp = doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib)+"&sort=path", "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("sort=path status = %d, want 200", resp.StatusCode)
	}
	rows = decodeSeriesList(t, resp)
	wantIDs(t, servedIDs(rows, func(d seriesDTO) string { return d.ID }),
		aa.ID, bb.ID, cc.ID, ongoing.ID)
	for _, d := range rows {
		if d.RecScore != 0 {
			t.Fatalf("sort=path computed scores (%v on %s) — the opt-out must serve unscored", d.RecScore, d.ID)
		}
	}
}

// TestGoldenCompletedSkipsResumeBonus is the spec's "Completed items skip
// the resume bonus" scenario: a completed item (positive progress row AND a
// watched-ledger row — the detector writes the ledger beside the position)
// scores its TAGS ONLY, while a mid-media item keeps the resume tier and
// tops the grid. The watched partition sinks the completed item below even
// the zero-score plain one — the partition WORKING is the served order's
// point — while its tags-only score stays observable on the wire.
func TestGoldenCompletedSkipsResumeBonus(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// The completed film: progress at the completion threshold plus the
	// watched row, with an action tag behind it.
	done := seedRecsItem(t, st, lib, "gld_done", "done.mkv", map[string]any{
		"_view":   map[string]any{"title": map[string]any{"value": "Done"}},
		"sources": map[string]any{recsMetaNS: map[string]any{"description": "d", "genres": []string{"action"}}},
	}, time.Time{})
	if _, err := st.PutProgress(ctx, done.ID, 5400, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	if err := st.InsertWatched(ctx, done.ID, lib, "", time.Now().UTC(), access.System()); err != nil {
		t.Fatalf("InsertWatched: %v", err)
	}
	// The mid-media film: a positive position, never completed.
	mid := seedRecsItem(t, st, lib, "gld_mid", "mid.mkv", map[string]any{
		"_view": map[string]any{"title": map[string]any{"value": "Mid"}},
	}, time.Time{})
	if _, err := st.PutProgress(ctx, mid.ID, 300, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	// A plain film: no facts, no tags — the floor the completed film's tag
	// component must still beat.
	plain := seedRecsItem(t, st, lib, "gld_plain", "plain.mkv", map[string]any{}, time.Time{})
	// action interest = 1 → the completed film's tag component = (1+1) = 2.
	if err := st.ApplyTagWeights(ctx, []string{"action"}, time.Now().UTC()); err != nil {
		t.Fatalf("ApplyTagWeights: %v", err)
	}

	resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib), "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	lr := decodeItems(t, resp)
	// The partition: every unwatched entry first (mid's resume tier, then
	// plain's zero at the alphabetical floor), the ledgered item LAST —
	// despite its score 2 beating plain's 0.
	wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), mid.ID, plain.ID, done.ID)
	scores := map[string]float64{}
	for _, d := range lr.Items {
		scores[d.ID] = d.RecScore
	}
	if scores[done.ID] != 2 {
		t.Fatalf("completed item rec_score = %v, want 2 (tags only — the resume bonus must be skipped)", scores[done.ID])
	}
	if scores[mid.ID] != 1000 {
		t.Fatalf("mid-media item rec_score = %v, want 1000 (the resume tier)", scores[mid.ID])
	}
}

// TestGoldenPhotoLibraryKeepsPathOrder is the spec's "Photo libraries keep
// path order regardless of score" scenario: a photo-scanner-module library
// (module id "image") listed under the scored DEFAULT stays in the store's
// path order, whatever its items carry — here the LAST-inserted photo holds
// a progress row, so the computed order would put it first if the carve-out
// branch ever slipped. No rec_score rides the wire. A scored sibling
// library beside it keeps the scored default, proving the carve-out holds
// by mechanism, not by a dulled composition.
func TestGoldenPhotoLibraryKeepsPathOrder(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	photoLib, err := st.CreateLibrary(ctx, "image", "/media/photos", "Photos")
	if err != nil {
		t.Fatalf("CreateLibrary(image): %v", err)
	}
	// Store (id) order: Alpha, Beta, Zulu — and Zulu carries the only
	// progress row, so the scored order would serve Zulu, Alpha, Beta.
	seedGoldenPhotoItem(t, st, photoLib, "gld_p1", "IMG_0001.jpg", "Alpha")
	seedGoldenPhotoItem(t, st, photoLib, "gld_p2", "IMG_0002.jpg", "Beta")
	zulu := seedGoldenPhotoItem(t, st, photoLib, "gld_p3", "IMG_0003.jpg", "Zulu")
	if _, err := st.PutProgress(ctx, zulu.ID, 42, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	// The scored sibling: the same shape in a serial-module library — its
	// progress item MUST still top the grid (the carve-out is per-library).
	scoredPlain := seedRecsItem(t, st, lib, "gld_g1", "gamma-a.mkv", map[string]any{}, time.Time{})
	scoredTop := seedRecsItem(t, st, lib, "gld_g2", "gamma-b.mkv", map[string]any{}, time.Time{})
	if _, err := st.PutProgress(ctx, scoredTop.ID, 700, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}

	// The scored default on the photo library: store path order, unscored.
	resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(photoLib), "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	lr := decodeItems(t, resp)
	wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }),
		"gld_p1", "gld_p2", "gld_p3")
	for _, d := range lr.Items {
		if wireHasRecScore(t, d) {
			t.Fatalf("photo item %s served rec_score — the carve-out must serve unscored", d.ID)
		}
	}

	// Score present or absent on the wire must not reorder: the explicit
	// opt-out serves the identical order.
	resp = doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(photoLib)+"&sort=path", "", adminToken)
	defer resp.Body.Close()
	lr = decodeItems(t, resp)
	wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }),
		"gld_p1", "gld_p2", "gld_p3")

	// The scored sibling library is untouched: its progress item tops.
	resp = doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib), "", adminToken)
	defer resp.Body.Close()
	lr = decodeItems(t, resp)
	wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }),
		scoredTop.ID, scoredPlain.ID)
}

// TestGoldenEpisodeTableNarrativeOrderUntouched pins the per-series episode
// table: /series/{id}/episodes keeps the store's narrative (relative_path)
// order and serves unscored rows even with scored facts all over the
// library — while the SAME episodes in the items grid DO reorder under the
// scored default, proving the table's order is untouched by mechanism, not
// by a missing score.
func TestGoldenEpisodeTableNarrativeOrderUntouched(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	show := seedRecsSeries(t, st, lib, "show", recsSeriesDoc("Show"))
	// Narrative order e1, e2, e3. Scored order inverts the head: e2 holds
	// the progress row (1000), e1 is the fresh unwatched episode of the
	// now-started series (500), e3 is plain.
	seedRecsItem(t, st, lib, "gld_e1", "show/e1.mkv", recsEpisodeDoc("show", "Pilot"), time.Time{})
	e2 := seedRecsItem(t, st, lib, "gld_e2", "show/e2.mkv", recsEpisodeDoc("show", "Second"), time.Now().AddDate(0, 0, -40))
	if _, err := st.PutProgress(ctx, e2.ID, 100, access.System()); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	seedRecsItem(t, st, lib, "gld_e3", "show/e3.mkv", recsEpisodeDoc("show", "Third"), time.Time{})

	// The episode table: narrative order, unscored.
	resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+show.ID+"/episodes", "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	lr := decodeItems(t, resp)
	wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }),
		"gld_e1", "gld_e2", "gld_e3")
	for _, d := range lr.Items {
		if wireHasRecScore(t, d) {
			t.Fatalf("episode-table row %s served rec_score — the table must stay unscored", d.ID)
		}
	}

	// The grid over the SAME episodes reorders: e2 (resume) above e1 (new
	// episode) above e3.
	resp = doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib), "", adminToken)
	defer resp.Body.Close()
	lr = decodeItems(t, resp)
	wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }),
		"gld_e2", "gld_e1", "gld_e3")
}
